package com.nodecockpit.customization
import org.junit.Assert.*
import org.junit.Test
class GlassLabStateTest {
 @Test fun catalogHasUniqueBoundedDefaults(){val c=GlassLabCatalog.controls;assertEquals(c.size,c.map{it.key}.toSet().size);for(spec in c){assertTrue(spec.initial.isFinite());assertTrue(spec.initial in spec.low..spec.high)}}
 @Test fun allNumericInputsRejectNonfiniteAndClamp(){val s=GlassLabState();for(c in GlassLabCatalog.controls){s.setNumber(c.key,Float.NaN);assertEquals(c.initial,s.number(c.key),0f);s.setNumber(c.key,Float.POSITIVE_INFINITY);assertEquals(c.initial,s.number(c.key),0f);s.setNumber(c.key,c.low-100);assertEquals(c.low,s.number(c.key),0f);s.setNumber(c.key,c.high+100);assertEquals(c.high,s.number(c.key),0f)}}
 @Test fun copyingDoesNotShareMutableConfiguration(){val a=GlassLabState();val b=a.copy();b.setNumber("progress",.2f);b.setFlag("rtl",true);b.setColor("inkColor",0);assertEquals(.55f,a.number("progress"),0f);assertFalse(a.flag("rtl"));assertEquals(-1,a.color("inkColor"));b.reset();assertEquals(.55f,b.number("progress"),0f)}
 @Test fun selectorsAndTextAreBounded(){val s=GlassLabState();s.profile=999;s.scene=-99;s.motion=999;s.background=999;s.text="a".repeat(1000);s.validateSelections();assertEquals(5,s.profile);assertEquals(0,s.scene);assertEquals(8,s.motion);assertEquals(4,s.background);assertEquals(256,s.text.length)}
 @Test fun notificationAndQsCountsRespectShaderBudgets(){val s=GlassLabState();s.scene=5;s.setNumber("count",16f);s.profile=3;assertEquals(13,GlassLabGeometry.regions(s,500f,300f,1f,0f).size);s.profile=4;val result=GlassLabGeometry.regions(s,500f,300f,1f,0f);assertEquals(16,result.size);for(r in result){assertTrue(r.left>=0&&r.top>=0&&r.width>0&&r.height>0);assertTrue(r.left+r.width<=500.01f);assertTrue(r.top+r.height<=300.01f)}}
 @Test fun emptyAndTinyLayoutsNeverProduceNegativeSizes(){val s=GlassLabState();assertTrue(GlassLabGeometry.regions(s,0f,300f,1f,0f).isEmpty());assertTrue(GlassLabGeometry.regions(s,Float.NaN,300f,1f,0f).isEmpty());for(scene in GlassLabCatalog.scenes.indices){s.scene=scene;for(r in GlassLabGeometry.regions(s,12f,12f,3f,.5f)){assertTrue(r.width.isFinite()&&r.height.isFinite());assertTrue(r.width>0&&r.height>0)}}}
 @Test fun progressSweepIsNotBackgroundMotion(){val s=GlassLabState();s.motion=5;assertEquals(.8f,GlassLabGeometry.progress(s,.8f),0f);s.motion=6;assertEquals(.55f,GlassLabGeometry.progress(s,.8f),0f)}
 @Test fun fadeAndResizeApplyCurrentPhase(){val s=GlassLabState();s.motion=3;assertEquals(0f,GlassLabGeometry.alpha(s,0f),0f);assertEquals(1f,GlassLabGeometry.alpha(s,1f),0f);s.motion=2;assertTrue(GlassLabGeometry.regions(s,500f,300f,1f,0f)[0].width<GlassLabGeometry.regions(s,500f,300f,1f,1f)[0].width)}
 @Test fun mergePreviewDoesNotOverwriteSecondaryWidthWithBlurFlag(){val a=GlassLabRect(20f,30f,100f,80f);val b=GlassLabRect(80f,30f,120f,80f);val packet=GlassLabGeometry.mergePacket(ByteArray(240),a,b,20f,24f,48f,1f);val bytes=java.nio.ByteBuffer.wrap(packet).order(java.nio.ByteOrder.nativeOrder());assertEquals(60f,bytes.getFloat(248),0f);assertEquals(40f,bytes.getFloat(252),0f);assertEquals(48f,bytes.getFloat(264),0f);val single=java.nio.ByteBuffer.wrap(GlassLabGeometry.mergePacket(ByteArray(240),a,null,20f,24f,48f,1f)).order(java.nio.ByteOrder.nativeOrder());assertEquals(0f,single.getFloat(248),0f);assertEquals(0f,single.getFloat(260),0f)}
 @Test fun secondaryShapeHasIndependentSizeAndBoundedRadius(){val s=GlassLabState();s.scene=4;s.setNumber("secondaryWidth",.5f);s.setNumber("secondaryHeight",.75f);val r=GlassLabGeometry.regions(s,500f,300f,1f,0f);assertEquals(r[0].width*.5f,r[1].width,.001f);assertEquals(r[0].height*.75f,r[1].height,.001f);val bytes=java.nio.ByteBuffer.wrap(GlassLabGeometry.mergePacket(ByteArray(240),r[0],r[1],100f,24f,0f,0f)).order(java.nio.ByteOrder.nativeOrder());assertTrue(bytes.getFloat(256)<=minOf(r[1].width,r[1].height)/2)}

 @Test fun backdropAndMaterialCanShareOneFinitePhaseSnapshot(){val snapshot=GlassLabGeometry.phase(400,1600f,true);assertEquals(0L,snapshot.first);assertEquals(.25f,snapshot.second,0f);assertEquals(.75f,GlassLabGeometry.phase(2000,1600f,true).second,0f);assertEquals(.5f,GlassLabGeometry.phase(9999,1600f,false).second,0f);assertEquals(0f,GlassLabGeometry.phase(-5,Float.NaN,true).second,0f);assertTrue(GlassLabGeometry.phase(100,0f,true).second.isFinite())}
 @Test fun interactiveScenesRespectProfileLimitsAndBounds(){val s=GlassLabState();s.setNumber("count",16f);s.profile=2;s.scene=6;assertEquals(2,GlassLabGeometry.regions(s,400f,250f,1f,0f).size);s.profile=4;assertEquals(16,GlassLabGeometry.regions(s,400f,250f,1f,0f).size);s.scene=7;assertEquals(6,GlassLabGeometry.regions(s,400f,250f,1f,0f).size);for(r in GlassLabGeometry.regions(s,12f,12f,3f,0f)){assertTrue(r.left>=0&&r.top>=0);assertTrue(r.left+r.width<=12.01f&&r.top+r.height<=12.01f)}}
}


